(async () => {
  const j = async (path, init) => { const r = await fetch(path, { headers: { 'content-type': 'application/json' }, ...init }); return r.json(); };
  const pepper = (await j('/api/bots')).bots.find((b) => b.name === 'Pepper');
  const { routine } = await j('/api/routines', { method: 'POST', body: JSON.stringify({ name: 'Morning inbox', prompt: 'Sum up my inbox in one line.', botId: pepper.id, schedule: { type: 'daily', time: '09:00', weekdays: [0, 1, 2, 3, 4, 5, 6] } }) });
  const runs = async () => (await j('/api/routines')).runs.filter((run) => run.routineId === routine.id);
  const until = async (test) => { for (let i = 0; i < 120; i++) { const all = await runs(); if (test(all)) return all; await new Promise((r) => setTimeout(r, 250)); } throw new Error('runs never settled'); };
  await fetch(`/api/routines/${routine.id}/run`, { method: 'POST' });
  await until((all) => all.some((run) => run.status === 'completed'));
  await fetch(`/api/routines/${routine.id}/run`, { method: 'POST' });
  const busy = await until((all) => all.some((run) => run.status === 'running'));
  const second = busy.find((run) => run.status === 'running');
  await fetch(`/api/routine-runs/${second.id}/cancel`, { method: 'POST' });
  await until((all) => all.some((run) => run.status === 'cancelled'));
  return (await runs()).map((run) => run.status);
})()

(() => {
  const spoken = (el) => [...el.children].filter((c) => c.getAttribute('aria-hidden') !== 'true').map((c) => c.textContent.trim()).filter(Boolean).join(', ');
  const rows = [...document.querySelectorAll('[data-routine-run]')];
  const list = rows[0].closest('ul');
  const box = document.createElement('div');
  box.style.cssText = 'margin:14px 0 0;padding:10px 12px;border-radius:12px;border:1px dashed color-mix(in srgb, var(--color-ink) 30%, transparent);font:12px/18px ui-monospace,Menlo,monospace;color:var(--color-ink);white-space:normal';
  box.innerHTML = '<div style="opacity:.6;margin-bottom:6px">Capture overlay: each run as a screen reader reads it</div>' + rows.map((r) => '<div>' + spoken(r).replace(/&/g,'&amp;').replace(/</g,'&lt;') + '</div>').join('');
  list.after(box);
  return rows.map(spoken);
})()
